"""Discharge-summary templating engine (educational).

Safety rails:
  * No eval/exec anywhere -- parsing is a single regex scan.
  * Substituted values are inserted literally and never re-scanned,
    so ``{{other_field}}`` inside a value is NOT expanded.
  * Unknown fields raise MissingFieldError listing ALL missing fields.
  * Unknown filters raise UnknownFilterError.
"""
from __future__ import annotations

import datetime as _dt
import re

_TOKEN = re.compile(
    r"(?P<esc>\{\{\{\{)"
    r"|(?P<if>\{\{#if\s+(?P<cond>\w+)\}\})"
    r"|(?P<endif>\{\{/if\}\})"
    r"|(?P<var>\{\{(?P<name>\w+)(?P<filters>(?:\|[^\}{]*?)?)\}\})"
)


class TemplateError(Exception):
    """Base class for template problems."""


class MissingFieldError(TemplateError):
    def __init__(self, missing):
        self.missing = list(missing)
        super().__init__("missing fields: " + ", ".join(self.missing))


class UnknownFilterError(TemplateError):
    pass


def _f_upper(value, arg):
    if arg:
        raise TemplateError("filter 'upper' takes no argument")
    return str(value).upper()


def _f_date(value, arg):
    if not isinstance(value, _dt.date):
        raise TemplateError("filter 'date' needs a datetime.date, got %r" % (value,))
    return value.strftime(arg or "%d %b %Y")


FILTERS = {"upper": _f_upper, "date": _f_date}


def _parse_filter_spec(spec):
    """'|upper' -> [('upper', None)]; '|date:%d %b %Y' -> [('date', '%d %b %Y')]."""
    out = []
    for part in spec.split("|"):
        if not part:
            continue
        name, sep, arg = part.partition(":")
        if name not in FILTERS:
            raise UnknownFilterError("unknown filter: %r" % name)
        out.append((name, arg if sep else None))
    return out


def _parse(template):
    """Scan template into nodes: ('text', s), ('var', name, spec), ('if', cond, body)."""
    tokens, pos = [], 0
    for m in _TOKEN.finditer(template):
        if m.start() != pos:
            tokens.append(("text", template[pos:m.start()]))
        pos = m.end()
        if m.group("esc"):
            tokens.append(("text", "{{"))
        elif m.group("if"):
            tokens.append(("if", m.group("cond")))
        elif m.group("endif"):
            tokens.append(("endif",))
        else:
            tokens.append(("var", m.group("name"), m.group("filters")))
    if pos != len(template):
        tokens.append(("text", template[pos:]))

    # Flat token list -> tree. No nesting: a second '{{#if' before '{{/if}' is an error.
    root, open_if = [], None
    for tok in tokens:
        target = root if open_if is None else open_if[2]
        if tok[0] == "if":
            if open_if is not None:
                raise TemplateError("nested {{#if}} blocks are not supported")
            open_if = ("if", tok[1], [])
            continue  # appended once we see its body is complete
        if tok[0] == "endif":
            if open_if is None:
                raise TemplateError("{{/if}} without matching {{#if}}")
            root.append(open_if)
            open_if = None
            continue
        target.append(tok)
    if open_if is not None:
        raise TemplateError("{{#if}} without matching {{/if}}")
    return root


def render(template, context):
    nodes = _parse(template)

    # Validation pass: collect ALL missing fields before rendering anything.
    def _vars(nodes):
        for tok in nodes:
            if tok[0] in ("var", "if"):
                yield tok[0], tok[1]
                if tok[0] == "if":
                    yield from _vars(tok[2])

    missing = {name for _, name in _vars(nodes) if name not in context}
    if missing:
        raise MissingFieldError(sorted(missing))
    for kind, name in _vars(nodes):
        if kind == "var":  # find its spec again for eager filter checking

    return _render_nodes(nodes, context)


def _render_nodes(nodes, context):
    out = []
    for tok in nodes:
        if tok[0] == "text":
            out.append(tok[1])
        elif tok[0] == "var":
            value = context[tok[1]]
            for fname, arg in _parse_filter_spec(tok[2]):
                value = FILTERS[fname](value, arg)
            out.append(str(value))  # inserted literally; never re-expanded
        elif context[tok[1]]:  # ('if', cond, body): truthy branch only
            out.append(_render_nodes(tok[2], context))
    return "".join(out)

