import json
from pathlib import Path

import pytest

from discharge_summary.engine import (
    MissingFieldError,
    UnknownFilterError,
    render,
)

TEMPLATES = Path(__file__).resolve().parent.parent / "discharge_summary" / "templates"


# --- plain substitution -------------------------------------------------

def test_plain_substitution():
    assert render("Hello {{name}}!", {"name": "World"}) == "Hello World!"


def test_multiple_plain_fields():
    out = render("{{a}}-{{b}}-{{a}}", {"a": "x", "b": "y"})
    assert out == "x-y-x"


# --- filters ------------------------------------------------------------

def test_upper_filter():
    assert render("{{name|upper}}", {"name": "ada lovelace"}) == "ADA LOVELACE"


def test_date_filter_takes_a_date_object():
    ctx = {"when": dt.date(2026, 8, 24)}
    assert render("{{when|date:%d %b %Y}}", ctx) == "24 Aug 2026"


def test_chained_filters():
    ctx = {"when": dt.date(2026, 1, 3)}
    assert render("{{when|date:%d %b %Y}}".replace("}}", "|upper}}"), ctx) \
        == "03 JAN 2026"


# --- aggregate missing-field error ---------------------------------------

def test_missing_fields_lists_all_at_once():
    with pytest.raises(MissingFieldError) as excinfo:
        render("{{alpha}} {{beta}} {{gamma}}", {"gamma": 1})
    assert set(excinfo.value.missing) == {"alpha", "beta"}
    # both named in the message, not just the first
    msg = str(excinfo.value)
    assert "alpha" in msg and "beta" in msg


# --- unknown filter ------------------------------------------------------

def test_unknown_filter_raises():
    with pytest.raises(UnknownFilterError):
        render("{{x|shout}}", {"x": "hi"})


# --- conditional blocks (no nesting) -------------------------------------

def test_if_block_true_path():
    t = "{{#if flag}}SEEN: {{value}}{{/if}}"
    assert render(t, {"flag": True, "value": 42}) == "SEEN: 42"


def test_if_block_false_path():
    t = "before{{#if flag}}HIDDEN {{secret}}{{/if}}after"
    assert render(t, {"flag": False, "secret": "x"}) == "beforeafter"


def test_nested_if_is_rejected():
    t = "{{#if a}}{{#if b}}x{{/if}}{{/if}}"
    from discharge_summary.engine import TemplateError
    with pytest.raises(TemplateError):
        render(t, {"a": True, "b": True})


