def test_escaped_braces_render_as_double_braces():
    assert render("{{{{literal}}}}", {}) == "{{literal}}"
    out = render("Use {{{{field}}}} syntax; real: {{field}}", {"field": "V"})
    assert out == "Use {{field}} syntax; real: V"


