def test_value_containing_template_syntax_is_inserted_literally():
    ctx = {"safe": "INJECTED", "evil": "{{safe}}"}
    assert render("{{evil}}", ctx) == "{{safe}}"          # not expanded at all
    out = render("{{evil}} vs {{safe}}", ctx)
    assert out == "{{safe}} vs INJECTED"                   # key assertion


